insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_ela_v1'
from (values
('110.6.b.2.A.i',3,'Which is the plural form of "child"?','["children", "childen", "childs", "childes"]'::jsonb,0,'Child has an irregular plural.','original'),
('110.6.b.2.A.i',3,'Which is the correct plural of "knife"?','["knifs", "knives", "knifies", "knifes"]'::jsonb,1,'Words ending in fe often change to ves.','original'),
('110.6.b.2.A.ii',3,'How many syllables are in the word "fantastic"?','["1", "4", "3", "2"]'::jsonb,2,'Fan-tas-tic has three parts.','original'),
('110.6.b.2.A.iii',4,'Which shows the correct syllable division?','["n-apkin", "napk-in", "na-pkin", "nap-kin"]'::jsonb,3,'Divide between two consonants.','original'),
('110.6.b.2.A.iv',3,'Which word has the prefix "pre-"?','["preview", "present", "prefer", "pretty"]'::jsonb,0,'Preview means to view before.','original'),
('110.6.b.2.A.v',3,'Which word has a base word plus the suffix -ful?','["rewrite", "thankful", "cheerless", "unkind"]'::jsonb,1,'Thank plus -ful.','original'),
('110.6.b.2.A.vi',2,'Which word is a high-frequency word that should be read quickly by sight?','["oxygen", "aquarium", "because", "xylophone"]'::jsonb,2,'Because appears very often in text.','original'),
('110.6.b.2.B.ii',3,'Which word correctly completes the sentence? "We ate our ___ at the picnic."','["mete''s", "meet", "mete", "meat"]'::jsonb,3,'Meat is food.','original'),
('110.6.b.2.B.vi',3,'What is the correct spelling when you add -ing to "hop"?','["hopping", "hoppeing", "hopeing", "hoping"]'::jsonb,0,'Double the consonant after a short vowel.','original'),
('110.6.b.2.B.vi',3,'What is the correct spelling when you add -ed to "carry"?','["caried", "carried", "carryed", "carryd"]'::jsonb,1,'Change y to i before -ed.','original'),
('110.6.b.3.A',3,'Which part of a dictionary entry tells how to say a word?','["the date", "the page number", "the pronunciation key", "the cover"]'::jsonb,2,'Pronunciation shows how to say it.','original'),
('110.6.b.3.B',3,'"The scientist was meticulous, checking every measurement twice." What does meticulous mean?','["careless", "sleepy", "loud", "very careful"]'::jsonb,3,'Checking twice shows great care.','original'),
('110.6.b.3.B',3,'Read: "The bat flew out of the cave." and "He swung the bat at the ball." What is the best way to tell which meaning is used?','["read the words around it", "look at the cover", "guess", "skip it"]'::jsonb,0,'Context shows the right meaning.','original'),
('110.6.b.3.B',4,'"After the long hike, the travelers were famished and ate everything at the table." What does famished mean?','["very cold", "very hungry", "very wet", "very tired"]'::jsonb,1,'They ate everything.','original'),
('110.6.b.3.C',3,'The root "graph" means write. What does "autograph" most likely mean?','["a type of car", "a long walk", "a person''s own signature", "a picture of food"]'::jsonb,2,'Auto means self.','original'),
('110.6.b.3.C',3,'The suffix -ment means "the act or result of." What does "enjoyment" mean?','["not enjoying", "before enjoying", "enjoying again", "the result of enjoying"]'::jsonb,3,'Add -ment to enjoy.','original'),
('110.6.b.3.C',4,'What does the root "meter" mean in "thermometer"?','["measure", "self", "hot", "write"]'::jsonb,0,'Meter means measure.','original'),
('110.6.b.3.D',3,'Which sentence uses the homophone correctly?','["The king began his rein.", "The king began his reign.", "The king began his rain.", "The king began his reen."]'::jsonb,1,'Reign means to rule.','original'),
('110.6.b.6.A',3,'Before reading a chapter on volcanoes for homework, what purpose could a student set?','["to copy the title", "to find a rhyme", "to learn how volcanoes erupt", "to count the pages"]'::jsonb,2,'A purpose guides reading.','original'),
('110.6.b.6.B',3,'Which question helps a reader deepen understanding while reading a story about a lost dog?','["How tall is a tree?", "Who is next?", "What color is my desk?", "Why did the dog leave home?"]'::jsonb,3,'It connects to the text.','original'),
('110.6.b.6.C',3,'A mystery''s chapter ends with a locked door and a strange sound. Which prediction is best?','["someone will open the door", "a clock will talk", "the author will change", "the story is over"]'::jsonb,0,'Details suggest the next event.','original'),
('110.6.b.6.D',3,'Which sentence helps a reader create a clear mental image?','["The barn was a barn.", "The dusty barn leaned to one side, its red paint peeling in long strips.", "It was old.", "There was a thing."]'::jsonb,1,'Sensory detail builds images.','original'),
('110.6.b.6.E',3,'A reader connects a story''s theme about courage to a news report about a rescue. This is a connection to...','["math", "punctuation", "society", "spelling"]'::jsonb,2,'It links to the world.','original'),
('110.6.b.6.F',4,'Read: "Jada checked her watch again and again as the bus failed to arrive." What can you infer?','["she lost her watch", "she loves buses", "she is asleep", "she is worried about being late"]'::jsonb,3,'Repeated checking shows worry.','original'),
('110.6.b.6.G',3,'Which detail is most important for the key idea of an article about how penguins stay warm?','["they huddle together", "ice is white", "some live in zoos", "penguins like fish"]'::jsonb,0,'Huddling is how they stay warm.','original'),
('110.6.b.6.H',4,'One article says honeybees make honey, and another says bees pollinate crops. What new understanding could a reader build?','["honey grows crops", "bees are useful in two ways", "crops make bees", "bees are useless"]'::jsonb,1,'Combining the facts builds new understanding.','original'),
('110.6.b.6.I',3,'A reader stops understanding a hard paragraph. Which is a good fix-up strategy?','["guess a random word", "skip the book", "annotate and reread it", "stop reading forever"]'::jsonb,2,'Rereading and annotating help.','original'),
('110.6.b.7.A',3,'A student says, "I know how Maya feels because my family moved too." This response is...','["an index", "a rhyme", "a plot summary", "a personal connection"]'::jsonb,3,'It ties to the student''s life.','original'),
('110.6.b.7.B',4,'Which response compares and contrasts two sources?','["Both texts discuss recycling, but one focuses on cities and the other on farms.", "Both are books.", "Texts have words.", "I like recycling."]'::jsonb,0,'It shows similarities and differences.','original'),
('110.6.b.7.C',3,'Which sentence uses text evidence?','["My uncle has a dog.", "The article says that wolves hunt in packs, so they are social animals.", "I think wolves are cool.", "Wolves are in zoos."]'::jsonb,1,'It cites the article.','original'),
('110.6.b.7.D',3,'Which is the best summary of a story in which a boy loses his kite, searches the park, and finds it with help from a friend?','["A friend is nice.", "The park is big.", "A boy lost his kite, searched, and found it with a friend''s help.", "Kites fly high."]'::jsonb,2,'It keeps events in order.','original'),
('110.6.b.7.E',3,'A student underlines key facts and writes questions in the margin while reading. This is called...','["rhyming", "scheduling", "skimming a menu", "annotating"]'::jsonb,3,'Annotating means marking the text.','original'),
('110.6.b.7.F',3,'A student learns the word "migrate" in science. Which sentence uses it correctly?','["Many geese migrate south each fall.", "My shoes migrate.", "The lunch migrated red.", "I migrate a pencil."]'::jsonb,0,'Migrate means to move seasonally.','original'),
('110.6.b.7.G',3,'During a discussion, a student says, "The author uses the storm to show the characters'' fear." This statement is about...','["a spelling rule", "an idea important to the meaning", "a font style", "a page number"]'::jsonb,1,'It explains the meaning.','original'),
('110.6.b.8.A',3,'A character in a story gives up her seat to a tired stranger, and the story ends with her smiling. Which theme is best supported?','["buses are crowded", "smiling is hard", "helping others brings joy", "strangers are dangerous"]'::jsonb,2,'The ending supports kindness.','original'),
('110.6.b.8.B',4,'At the start, Leo is afraid to speak in class. By the end, he gives a speech. How did Leo change?','["He moved away.", "He became shorter.", "He became angry.", "He became more confident."]'::jsonb,3,'He grew braver.','original'),
('110.6.b.8.C',3,'Which part of the plot shows the events leading up to the climax?','["rising action", "resolution", "title", "falling action"]'::jsonb,0,'Rising action builds tension.','original'),
('110.6.b.8.C',3,'Which part of the plot comes right after the climax?','["rising action", "falling action", "exposition", "setting"]'::jsonb,1,'Falling action follows the turning point.','original'),
('110.6.b.8.D',4,'A story set during a long drought on a farm in the 1930s shows how settings can...','["replace the plot", "erase the theme", "shape the characters'' problems", "change the author"]'::jsonb,2,'Setting influences events.','original'),
('110.6.b.9.A',3,'A tall tale usually includes...','["a recipe", "a list of facts", "a dictionary", "an exaggerated hero"]'::jsonb,3,'Tall tales exaggerate.','original'),
('110.6.b.9.A',3,'A legend is a story that...','["is based on a person or event from the past, often with exaggeration", "has no characters", "is only a poem", "is a science report"]'::jsonb,0,'Legends mix history and fiction.','original'),
('110.6.b.9.B',3,'"The wind whispered through the trees." This is an example of...','["a rhyme", "personification", "a fact", "a prefix"]'::jsonb,1,'Wind is given a human action.','original'),
('110.6.b.9.B',3,'"Her smile was a ray of sunshine." What kind of figurative language is it?','["a fact", "a simile", "a metaphor", "a definition"]'::jsonb,2,'It compares without like or as.','original'),
('110.6.b.9.C',3,'In a script, a character''s name followed by a colon is a...','["climax", "stage direction", "title", "character tag"]'::jsonb,3,'It shows who speaks.','original'),
('110.6.b.9.C',3,'A play is divided into major sections called...','["acts", "glossaries", "stanzas", "chapters"]'::jsonb,0,'Plays use acts and scenes.','original'),
('110.6.b.9.D.i',3,'A text about Texas bluebonnets discusses how they grow, when they bloom, and how to protect them. What is the central idea?','["spring is warm", "bluebonnets are important Texas flowers", "seeds are small", "flowers are red"]'::jsonb,1,'Details support the main idea.','original'),
('110.6.b.9.D.ii',3,'Which text feature helps a reader know how to say a hard science word?','["date line", "map", "pronunciation guide", "index"]'::jsonb,2,'Pronunciation guides spell sounds.','original'),
('110.6.b.9.D.ii',3,'A diagram of the water cycle helps the reader...','["find the author", "skip the text", "count syllables", "understand the steps visually"]'::jsonb,3,'Diagrams show processes.','original'),
('110.6.b.9.D.iii',3,'An article tells how frogs and toads are alike and different. The pattern is...','["compare and contrast", "sequence", "cause and effect", "description of a place"]'::jsonb,0,'It shows similarities and differences.','original'),
('110.6.b.9.E.i',3,'A student writes, "Kids have nowhere to play, so we need a new park in town." What is the claim?','["Kids play.", "The town should build a park.", "Parks are green.", "Towns are big."]'::jsonb,1,'The claim is the argument''s main point.','original'),
('110.6.b.9.E.ii',4,'An author argues for a longer school year and cites test scores. How does the author use facts?','["to hide the claim", "to rhyme", "to support the argument", "to change the topic"]'::jsonb,2,'Facts back the claim.','original'),
('110.6.b.9.E.iii',3,'A guide titled "How to Train a Puppy" is meant for...','["bakers", "doctors", "astronauts", "new dog owners"]'::jsonb,3,'The audience is people with puppies.','original'),
('110.6.b.9.F',3,'Which is a characteristic of a digital text?','["links that take you to more information", "a paper cover", "a stapled spine", "a printed index only"]'::jsonb,0,'Hyperlinks are digital.','original'),
('110.6.b.10.A',3,'An author writes a story about a girl who saves a lost kitten. Which is the likely message?','["cats are small", "care for animals in need", "rain is wet", "girls run fast"]'::jsonb,1,'The message is about compassion.','original'),
('110.6.b.10.B',3,'An author puts events in order from first to last. This helps the reader...','["count words", "find rhymes", "follow the sequence", "skip pages"]'::jsonb,2,'Chronological order shows events.','original'),
('110.6.b.10.C',3,'Why might an author use bold type for a vocabulary word?','["to change its meaning", "to hide it", "to add rhyme", "so the reader notices it"]'::jsonb,3,'Bold draws attention.','original'),
('110.6.b.10.D',3,'"The leaves danced in the autumn wind." What does this imagery help the reader see?','["leaves moving lightly", "a quiet room", "a bowl of soup", "a heavy rock"]'::jsonb,0,'Danced gives movement.','original'),
('110.6.b.10.D',4,'"Slippery snakes slid slowly." Which sound device is used?','["onomatopoeia", "alliteration", "assonance", "hyperbole"]'::jsonb,1,'The s sound repeats at the start.','original'),
('110.6.b.10.E',3,'A narrator says "she" and "they" to tell about the characters but is not in the story. This is...','["first-person point of view", "second person", "third-person point of view", "a conclusion"]'::jsonb,2,'Third person uses he, she, they.','original'),
('110.6.b.10.F',3,'Which sentence has a more formal voice?','["Just get it done, okay?", "Yeah, whatever.", "No way, dude.", "Please complete the assignment before the deadline."]'::jsonb,3,'Formal language avoids slang.','original'),
('110.6.b.10.G',3,'An author begins an article with a short true story about a girl who helped clean a beach. This short story is called a(n)...','["anecdote", "index", "glossary", "chapter"]'::jsonb,0,'An anecdote is a brief story.','original'),
('110.6.b.11.A',2,'Which is a strategy for planning a first draft?','["erasing the page", "brainstorming ideas", "publishing it", "printing the final copy"]'::jsonb,1,'Brainstorming generates ideas.','original'),
('110.6.b.11.B.i',3,'Which word is a transition that shows order?','["tiny", "green", "first", "banana"]'::jsonb,2,'First shows sequence.','original'),
('110.6.b.11.B.i',3,'Which sentence would work best as the conclusion of an essay about why exercise matters?','["Birds sing.", "Next, I got a pizza.", "Here is a list.", "In conclusion, exercise keeps our bodies healthy and strong."]'::jsonb,3,'A conclusion wraps up the main point.','original'),
('110.6.b.11.B.ii',3,'Which detail best supports the idea that dogs are loyal pets?','["Dogs often wait at the door for their owners to come home.", "Birds fly.", "Cats nap a lot.", "Dogs have four legs."]'::jsonb,0,'The detail supports the idea.','original'),
('110.6.b.11.C',3,'Which revision fixes a repeated word? "The dog ran fast. The dog ran home."','["Fast dog home.", "The dog ran fast and headed home.", "The dog dog ran.", "The ran dog."]'::jsonb,1,'Combining removes repeats.','original'),
('110.6.b.11.C',3,'Which sentence has the best word choice for "The cake was good"?','["The cake was thing.", "The cake was it.", "The cake was moist and delicious.", "The cake was cake."]'::jsonb,2,'Specific words add clarity.','original'),
('110.6.b.11.D.i',3,'Which is a run-on sentence?','["I like pizza.", "I like pizza, and my brother likes tacos.", "My brother likes tacos.", "I like pizza my brother likes tacos."]'::jsonb,3,'Two sentences are joined without punctuation.','original'),
('110.6.b.11.D.i',4,'Which is a sentence fragment?','["Because the bell rang.", "We walked home.", "The bell rang.", "The class left."]'::jsonb,0,'It does not express a complete thought.','original'),
('110.6.b.11.D.ii',3,'What is the past tense of the irregular verb "swim"?','["swum", "swam", "swimed", "swimmed"]'::jsonb,1,'Swim becomes swam.','original'),
('110.6.b.11.D.ii',3,'Which sentence uses an irregular past-tense verb correctly?','["She writed a long letter.", "She write a long letter.", "She wrote a long letter.", "She writes a long letter yesterday."]'::jsonb,2,'Wrote is the past tense of write.','original'),
('110.6.b.11.D.iii',3,'Which word is a plural noun?','["cheese", "mouse", "mouses", "mice"]'::jsonb,3,'Mice is the plural of mouse.','original'),
('110.6.b.11.D.iii',3,'Which is a proper noun?','["Texas", "mountain", "state", "river"]'::jsonb,0,'Texas names a specific place.','original'),
('110.6.b.11.D.iv',3,'Which sentence uses the correct superlative form?','["This is the most tallest tree in the park.", "This is the tallest tree in the park.", "This is a taller tree in the park.", "This is the tallest tree than the park."]'::jsonb,1,'Tallest compares three or more.','original'),
('110.6.b.11.D.v',3,'Which word is an adverb of frequency?','["quietly", "very", "always", "yesterday"]'::jsonb,2,'Always tells how often.','original'),
('110.6.b.11.D.v',3,'Which word is an adverb of degree?','["often", "never", "tomorrow", "extremely"]'::jsonb,3,'Extremely tells how much.','original'),
('110.6.b.11.D.vi',3,'Which sentence contains a preposition?','["The squirrel jumped over the fence.", "Squirrels are quick.", "The squirrel ate.", "The squirrel jumped happily."]'::jsonb,0,'Over shows position.','original'),
('110.6.b.11.D.vii',3,'Which sentence uses a reflexive pronoun correctly?','["Ana taught hisself to swim.", "Ana taught herself to swim.", "Ana taught themself.", "Ana taught yourselves."]'::jsonb,1,'Herself refers back to Ana.','original'),
('110.6.b.11.D.viii',3,'Which sentence has a compound subject?','["They sat down.", "Ben is playing chess.", "Ben and Mia are playing chess.", "Mia plays quietly."]'::jsonb,2,'Two subjects share one verb.','original'),
('110.6.b.11.D.ix',3,'Which is a historical document whose name needs capital letters?','["my notebook", "the shopping list", "a letter", "the Constitution"]'::jsonb,3,'Historical documents are capitalized.','original'),
('110.6.b.11.D.ix',3,'Which of these is a book title that needs capital letters?','["Charlotte''s Web", "our desk", "a pencil", "my backpack"]'::jsonb,0,'Titles of books are capitalized.','original'),
('110.6.b.11.D.x',4,'Which sentence uses a comma correctly in a compound sentence?','["I wanted, to swim but the pool was closed.", "I wanted to swim, but the pool was closed.", "I wanted to swim but, the pool was closed.", "I wanted to swim but the pool, was closed."]'::jsonb,1,'A comma comes before the conjunction.','original'),
('110.6.b.11.D.x',3,'Which sentence punctuates dialogue correctly?','["\"Let''s go said Maya.\"", "\"Let''s go\" said, Maya.", "\"Let''s go,\" said Maya.", "Let''s go, \"said Maya.\""]'::jsonb,2,'Commas belong inside the quotes.','original'),
('110.6.b.11.D.x',3,'Which phrase shows plural possession correctly?','["the student''s'' books", "the studentses books", "the students books''", "the students'' books"]'::jsonb,3,'The plural students takes an apostrophe after s.','original'),
('110.6.b.12.A',3,'Which sentence would begin a personal narrative well?','["Last summer, I learned to ride a bike at my grandmother''s house.", "The end.", "Here is a chart.", "Bicycles have two wheels."]'::jsonb,0,'It sets the scene.','original'),
('110.6.b.12.A',3,'A poem can use all of these EXCEPT...','["imagery", "a table of contents", "rhyme", "stanzas"]'::jsonb,1,'A table of contents belongs in a book.','original'),
('110.6.b.12.B',3,'A good informational composition has...','["no organization", "only opinions", "a clear central idea with facts", "a made-up story only"]'::jsonb,2,'Informational writing uses facts.','original'),
('110.6.b.12.C',3,'In an opinion essay, reasons should...','["be copied", "change the topic", "be left out", "support the writer''s claim"]'::jsonb,3,'Reasons back the opinion.','original'),
('110.6.b.12.D',3,'A letter that asks a museum for information should include...','["a polite request and clear question", "a joke only", "a recipe", "a drawing only"]'::jsonb,0,'It states what you want to know.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
